package com.lmspilot.notification.domain; import jakarta.persistence.*;import java.io.*;import java.util.*;
@Entity @Table(name="news_attachments") @IdClass(NewsAttachmentId.class) public class NewsAttachmentEntity{@Id public UUID newsId;@Id public UUID fileId;public NewsAttachmentEntity(){}} class NewsAttachmentId implements Serializable{public UUID newsId;public UUID fileId;public NewsAttachmentId(){}public boolean equals(Object o){return o instanceof NewsAttachmentId x&&Objects.equals(newsId,x.newsId)&&Objects.equals(fileId,x.fileId);}public int hashCode(){return Objects.hash(newsId,fileId);}}
